1	package server
2	
3	import (
4		"encoding/json"
5		"errors"
6		"net/http"
7		"strings"
8	
9		"github.com/alicegogogogogo/local-first-sync-service/internal/store"
10	)
11	
12	// crdtOpIn is one element of a CRDT submission. Exactly one content field is
13	// meaningful depending on the declared document type: value for a counter,
14	// elements for a grow-only set.
15	type crdtOpIn struct {
16		ID       string          `json:"id"`
17		Value    json.RawMessage `json:"value"`
18		Elements []string        `json:"elements"`
19	}
20	
21	// crdtOpsRequest is the body of POST .../crdt/ops.
22	type crdtOpsRequest struct {
23		DeviceID string     `json:"deviceId"`
24		Type     string     `json:"type"`
25		Ops      []crdtOpIn `json:"ops"`
26	}
27	
28	// handleCRDTOps accepts a batch of CRDT operations for a document.
29	//
30	// The batch declares the document's type; the first accepted batch fixes it to
31	// counter or gset and every later batch must declare the same type. Two
32	// batches racing to declare different types serialize in one transaction:
33	// exactly one takes effect and the other is a 409 that writes nothing.
34	//
35	// The strict body contract matches the other JSON endpoints: application/json,
36	// one JSON value, no trailing content, a non-empty deviceId, a valid type, a
37	// non-empty ops array of elements with non-empty ids, no in-batch duplicate
38	// ids, and type-correct content (counter: an integer value; gset: an elements
39	// array). Any violation is a 400 with zero writes.
40	func handleCRDTOps(s *store.Store, w http.ResponseWriter, r *http.Request) {
41		documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
42	
43		var req crdtOpsRequest
44		if !decodeJSONBody(w, r, &req) {
45			return
46		}
47		if req.DeviceID == "" {
48			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
49			return
50		}
51		if req.Type != store.CRDTTypeCounter && req.Type != store.CRDTTypeGSet {
52			writeError(w, http.StatusBadRequest, `type must be "counter" or "gset"`)
53			return
54		}
55		if len(req.Ops) == 0 {
56			writeError(w, http.StatusBadRequest, "ops must be a non-empty array")
57			return
58		}
59	
60		ops := make([]store.CRDTOp, len(req.Ops))
61		seen := make(map[string]struct{}, len(req.Ops))
62		for i, op := range req.Ops {
63			if op.ID == "" {
64				writeError(w, http.StatusBadRequest, "each op must have a non-empty string id")
65				return
66			}
67			if _, dup := seen[op.ID]; dup {
68				writeError(w, http.StatusBadRequest, "duplicate op id within batch: "+op.ID)
69				return
70			}
71			seen[op.ID] = struct{}{}
72	
73			crdtOp := store.CRDTOp{ID: op.ID, DeviceID: req.DeviceID}
74			switch req.Type {
75			case store.CRDTTypeCounter:
76				v, ok := parseNonNegativeInt(op.Value)
77				if !ok {
78					writeError(w, http.StatusBadRequest, "each counter op must carry an integer value >= 0")
79					return
80				}
81				// Re-marshal the canonical integer so idempotency compares the
82				// decoded value rather than the client's literal formatting.
83				raw, _ := json.Marshal(v)
84				crdtOp.Value = raw
85			case store.CRDTTypeGSet:
86				if len(op.Elements) == 0 {
87					writeError(w, http.StatusBadRequest, "each gset op must add at least one element")
88					return
89				}
90				for _, element := range op.Elements {
91					if element == "" {
92						writeError(w, http.StatusBadRequest, "gset elements must be non-empty strings")
93						return
94					}
95				}
96				crdtOp.Elements = op.Elements
97			}
98			ops[i] = crdtOp
99		}
100	
101		results, err := s.SubmitCRDTOps(documentID, req.Type, ops)
102		if err != nil {
103			var conflict *store.ErrCRDTConflict
104			switch {
105			case errors.Is(err, store.ErrDeviceNotFound):
106				writeError(w, http.StatusNotFound, "device not found")
107			case errors.Is(err, store.ErrPermissionDenied):
108				writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
109			case errors.As(err, &conflict):
110				writeError(w, http.StatusConflict, conflict.Error())
111			default:
112				writeError(w, http.StatusInternalServerError, "failed to commit crdt ops")
113			}
114			return
115		}
116	
117		writeJSON(w, http.StatusOK, map[string]any{"results": results})
118	}
119	
120	// handleCRDTState returns the document's current type and merged result. A
121	// document with no committed operations has no state yet and answers 404.
122	func handleCRDTState(s *store.Store, w http.ResponseWriter, r *http.Request) {
123		documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
124	
125		state, err := s.GetCRDTState(documentID)
126		if err != nil {
127			if errors.Is(err, store.ErrCRDTNotFound) {
128				writeError(w, http.StatusNotFound, "crdt state not found")
129				return
130			}
131			writeError(w, http.StatusInternalServerError, "failed to load crdt state")
132			return
133		}
134	
135		// Marshal through a concrete shape so the value stays a native JSON number
136		// or array rather than an escaped blob.
137		writeJSON(w, http.StatusOK, map[string]any{
138			"type":  state.Type,
139			"value": json.RawMessage(state.Value),
140		})
141	}
142	
143	// malformedCRDTPath reports whether p targets the CRDT namespace but is not at
144	// one of the two exact endpoints:
145	//
146	//	POST/GET /v1/documents/{documentID}/crdt/ops
147	//	GET      /v1/documents/{documentID}/crdt/state
148	//
149	// A missing/empty document id, a trailing slash, extra path segments, or a
150	// "crdt" segment in any position short of that shape is a malformed 400 rather
151	// than ServeMux's redirect or plain-text 404/405, so the new endpoints never
152	// redirect or emit HTML. The keyword is matched only past the documentID
153	// position, so a document literally named "crdt" keeps its ordinary routes.
154	func malformedCRDTPath(p string) bool {
155		rest, ok := strings.CutPrefix(p, "/v1/documents/")
156		if !ok {
157			return false
158		}
159		segs := strings.Split(rest, "/")
160		for i, seg := range segs {
161			if seg == "crdt" && i > 0 {
162				if len(segs) != 3 || segs[0] == "" {
163					return true
164				}
165				switch segs[2] {
166				case "ops", "state":
167					return false
168				default:
169					return true
170				}
171			}
172		}
173		return false
174	}
